const key = String($env.GITS_API_KEY ?? '').trim();

return [{
  json: {
    routeNames: ['평촌대로', '시민대로', '흥안대로', '관악대로', '귀인로'],
    hasKey: key.length > 0,
    ok: false,
    reason: key.length > 0 ? null : 'NO_KEY',
    missingRouteNames: [],
    routeCount: 0,
    linkCount: 0,
    upserted: 0,
    softDeleted: 0,
  },
}];

const context = $input.first().json;

return [{
  json: {
    ok: false,
    reason: context.reason || 'UNKNOWN',
    missingRouteNames: context.missingRouteNames || [],
    routeCount: Number(context.routeCount || 0),
    linkCount: Number(context.linkCount || 0),
    upserted: Number(context.upserted || 0),
    softDeleted: Number(context.softDeleted || 0),
  },
}];

const settings = $('설정').first().json;
const response = $input.first().json;
const status = Number(response.statusCode);
const body = typeof response.body === 'string' ? response.body : '';

function decodeXml(value) {
  return value
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, String.fromCharCode(34))
    .replace(/&apos;/g, String.fromCharCode(39))
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCodePoint(parseInt(code, 16)))
    .replace(/&amp;/g, '&');
}

function tagValue(xml, tagName) {
  const match = xml.match(new RegExp(`<${tagName}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tagName}>`, 'i'));
  return match ? decodeXml(match[1].replace(/^\s*<!\[CDATA\[/, '').replace(/\]\]>\s*$/, '').trim()) : null;
}

function findJsonValue(value, key) {
  if (Array.isArray(value)) {
    for (const child of value) {
      const found = findJsonValue(child, key);
      if (found != null) return found;
    }
    return null;
  }
  if (!value || typeof value !== 'object') return null;
  if (Object.prototype.hasOwnProperty.call(value, key) && value[key] != null) return value[key];
  for (const child of Object.values(value)) {
    const found = findJsonValue(child, key);
    if (found != null) return found;
  }
  return null;
}

function jsonRecords(value, anchor) {
  const records = [];
  function visit(node) {
    if (Array.isArray(node)) {
      for (const child of node) visit(child);
      return;
    }
    if (!node || typeof node !== 'object') return;
    let childHasRecord = false;
    for (const child of Object.values(node)) {
      const before = records.length;
      visit(child);
      if (records.length > before) childHasRecord = true;
    }
    if (!childHasRecord && Object.prototype.hasOwnProperty.call(node, anchor)) records.push(node);
  }
  visit(value);
  return records;
}

function xmlRecords(xml, anchor, fields) {
  const root = { children: [] };
  const stack = [root];
  const pattern = /<\/?([A-Za-z_][\w:.-]*)(?:\s[^>]*)?\s*\/?\s*>/g;
  let match;
  while ((match = pattern.exec(xml)) !== null) {
    const token = match[0];
    const name = match[1].split(':').pop();
    if (token.startsWith('</')) {
      for (let index = stack.length - 1; index > 0; index -= 1) {
        if (stack[index].name === name) {
          const node = stack[index];
          node.inner = xml.slice(node.contentStart, match.index);
          stack.length = index;
          break;
        }
      }
    } else if (!token.endsWith('/>')) {
      const node = { name, contentStart: pattern.lastIndex, inner: '', children: [] };
      stack[stack.length - 1].children.push(node);
      stack.push(node);
    }
  }
  function qualifies(node) {
    if (!node.inner || tagValue(node.inner, anchor) == null) return false;
    return fields.some((field) => field !== anchor && tagValue(node.inner, field) != null);
  }
  const records = [];
  function collect(node) {
    const qualifiedChildren = node.children.filter(qualifies);
    if (qualifies(node) && qualifiedChildren.length === 0) {
      records.push(node.inner);
      return;
    }
    for (const child of node.children) collect(child);
  }
  for (const child of root.children) collect(child);
  return records;
}

let parsedJson = null;
try { parsedJson = JSON.parse(body); } catch {}
const headerCdRaw = parsedJson == null ? tagValue(body, 'headerCd') : findJsonValue(parsedJson, 'headerCd');
const headerCd = headerCdRaw == null ? null : String(headerCdRaw).trim();
if (status !== 200 || headerCd !== '0') {
  const reason = status !== 200
    ? (Number.isInteger(status) ? `HTTP_${status}` : 'HTTP_ERROR')
    : headerCd && /^[A-Za-z0-9_-]{1,50}$/.test(headerCd) ? `GITS_${headerCd}` : 'INVALID_DATA';
  return [{ json: { ...settings, ok: false, reason } }];
}

const records = parsedJson == null
  ? xmlRecords(body, 'routeId', ['routeId', 'routeNm'])
  : jsonRecords(parsedJson, 'routeId');
const roads = [];
let invalid = false;
for (const record of records) {
  const get = (field) => typeof record === 'string' ? tagValue(record, field) : findJsonValue(record, field);
  const routeNameValue = get('routeNm');
  const routeName = routeNameValue == null ? null : String(routeNameValue).trim();
  if (!settings.routeNames.includes(routeName)) continue;
  const routeIdValue = get('routeId');
  const routeId = routeIdValue == null ? '' : String(routeIdValue).trim();
  if (!routeId || routeId.length > 20) {
    invalid = true;
    continue;
  }
  if (!roads.some((road) => road.routeId === routeId)) roads.push({ routeId, routeName });
}
const foundNames = new Set(roads.map((road) => road.routeName));
const missingRouteNames = settings.routeNames.filter((name) => !foundNames.has(name));

return [{
  json: {
    ...settings,
    ok: !invalid,
    reason: invalid ? 'INVALID_DATA' : null,
    roads,
    routeCount: roads.length,
    missingRouteNames,
    hasRoads: roads.length > 0,
  },
}];

