for (const item of $input.all()) {
  const response = item.json;
  const status = Number(response.statusCode);
  const body = typeof response.body === 'string' ? response.body : '';
  let parsedJson = null;
  try { parsedJson = JSON.parse(body); } catch {}
  const headerCdRaw = parsedJson == null ? tagValue(body, 'headerCd') : findJsonValue(parsedJson, 'headerCd');
  const headerCd = headerCdRaw == null ? null : String(headerCdRaw).trim();
  if (status !== 200 || headerCd !== '0') {
    failureReason ||= status !== 200
      ? (Number.isInteger(status) ? `HTTP_${status}` : 'HTTP_ERROR')
      : headerCd && /^[A-Za-z0-9_-]{1,50}$/.test(headerCd) ? `GITS_${headerCd}` : 'INVALID_DATA';
    continue;
  }

  const records = parsedJson == null
    ? xmlRecords(body, 'linkId', ['linkId', 'routeWay', 'startNodeNm', 'endNodeNm', 'linkLength'])
    : jsonRecords(parsedJson, 'linkId');
  for (const record of records) {
    const get = (field) => typeof record === 'string' ? tagValue(record, field) : findJsonValue(record, field);
    const linkIdValue = get('linkId');
    const startNodeValue = get('startNodeNm');
    const endNodeValue = get('endNodeNm');
    const lengthText = get('linkLength');
    const linkId = linkIdValue == null ? '' : String(linkIdValue).trim();
    const startNodeName = startNodeValue == null ? '' : String(startNodeValue).trim();
    const endNodeName = endNodeValue == null ? '' : String(endNodeValue).trim();
    const length = lengthText == null ? NaN : Number(String(lengthText).trim());
    if (!linkId || linkId.length > 20 || !startNodeName || !endNodeName || !Number.isFinite(length) || length < 0) {
      failureReason ||= 'INVALID_DATA';
      continue;
    }
    if (links.some((link) => link.linkId === linkId)) continue;
    const routeWayValue = get('routeWay');
    links.push({
      linkId,
      routeId: String(response.routeId),
      roadName: String(response.routeName),
      startNodeName,
      endNodeName,
      routeWay: routeWayValue == null || String(routeWayValue).trim() === '' ? null : String(routeWayValue).trim(),
      distanceM: Math.round(length),
    });
  }
}

return [{
  json: {
    ...context,
    ok: failureReason === null,
    reason: failureReason,
    links,
    linkCount: links.length,
  },
}];

const context = $input.first().json;

return [{
  json: {
    ...context,
    ok: true,
    reason: null,
    links: [],
    linkCount: 0,
  },
}];

const context = $input.first().json;

return [{
  json: {
    ...context,
    linksJson: JSON.stringify(context.links),
  },
}];

const context = $('정상 링크 적재 준비').first().json;
const failed = $input.all().some((item) => item.json.error != null);

return [{
  json: {
    ...context,
    ok: !failed,
    reason: failed ? 'DB_UPSERT_FAILED' : null,
    upserted: failed ? 0 : context.links.length,
  },
}];

const context = $('정상 링크 적재 판정').first().json;
const rows = $input.all().map((item) => item.json);
const failed = rows.some((row) => row.error != null);
const countRow = rows.find((row) => row.STALE_COUNT != null);
const staleCount = countRow ? Number(countRow.STALE_COUNT) : null;
const validCount = Number.isSafeInteger(staleCount) && staleCount >= 0;

return [{
  json: {
    ...context,
    ok: !failed && validCount,
    reason: failed ? 'DB_STALE_COUNT_FAILED' : validCount ? null : 'DB_STALE_COUNT_INVALID',
    staleCount: validCount ? staleCount : 0,
  },
}];

const context = $('삭제 대상 조회 판정').first().json;
const failed = $input.all().some((item) => item.json.error != null);

return [{
  json: {
    ...context,
    ok: !failed,
    reason: failed ? 'DB_SOFT_DELETE_FAILED' : null,
    softDeleted: failed ? 0 : context.staleCount,
  },
}];

const context = $input.first().json;

return [{
  json: {
    ok: true,
    reason: null,
    missingRouteNames: context.missingRouteNames,
    routeCount: context.routeCount,
    linkCount: context.linkCount,
    upserted: context.upserted,
    softDeleted: context.softDeleted,
  },
}];
